  "正在重试 {0} 段": {"zh-TW": "正在重試 {0} 段", "en": "Retrying {0} sections", "ko": "{0}개 구간 재시도 중"},
  "{0} 段解析失败，已保留成功结果": {"zh-TW": "{0} 段解析失敗，已保留成功結果", "en": "{0} sections failed; completed results are retained", "ko": "{0}개 구간 실패, 완료된 결과는 보존됨"},
