  "第 {0}/{1} 段": {"zh-TW": "第 {0}/{1} 段", "en": "Chunk {0}/{1}", "ko": "{0}/{1}번째 구간"},
  "正在连接模型…": {"zh-TW": "正在連線模型…", "en": "Connecting to the model…", "ko": "모델에 연결하는 중…"},
  // API route and upstream proxy errors
  "服务器错误": {"zh-TW": "伺服器錯誤", "en": "Server error", "ko": "서버 오류"},
  "处理请求时出错": {"zh-TW": "處理請求時發生錯誤", "en": "An error occurred while processing the request", "ko": "요청을 처리하는 중 오류가 발생했습니다"},
  "上游接口返回空错误响应": {"zh-TW": "上游介面傳回空白的錯誤回應", "en": "The upstream API returned an empty error response", "ko": "상위 API가 빈 오류 응답을 반환했습니다"},
  "上游流式响应空闲超时，请重试。": {"zh-TW": "上游串流回應閒置逾時，請再試一次。", "en": "The upstream stream stopped responding. Please try again.", "ko": "상위 스트리밍 응답이 멈췄습니다. 다시 시도해 주세요."},
  "流式响应创建失败": {"zh-TW": "串流回應建立失敗", "en": "Could not create the streaming response", "ko": "스트리밍 응답을 만들지 못했습니다"},
  "缺少必要的prompt参数": {"zh-TW": "缺少必要的 prompt 參數", "en": "Missing required prompt parameter", "ko": "필수 prompt 매개변수가 없습니다"},
  "缺少必要的参数": {"zh-TW": "缺少必要的參數", "en": "Missing required parameters", "ko": "필수 매개변수가 없습니다"},
  "缺少消息内容": {"zh-TW": "缺少訊息內容", "en": "Missing message content", "ko": "메시지 내용이 없습니다"},
  "缺少必要的文本内容": {"zh-TW": "缺少必要的文字內容", "en": "Missing required text", "ko": "필수 텍스트가 없습니다"},
  "请求体解析失败，请确保发送有效的JSON格式": {"zh-TW": "請求內容解析失敗，請確認傳送的是有效的 JSON 格式", "en": "Could not parse the request body. Make sure it is valid JSON.", "ko": "요청 본문을 해석하지 못했습니다. 올바른 JSON 형식인지 확인해 주세요."},
  "图片数据太大，请压缩后重试": {"zh-TW": "圖片資料太大，請壓縮後再試一次", "en": "The image is too large. Please compress it and try again.", "ko": "이미지가 너무 큽니다. 압축한 뒤 다시 시도해 주세요."},
  "缺少必要的图片数据": {"zh-TW": "缺少必要的圖片資料", "en": "Missing image data", "ko": "이미지 데이터가 없습니다"},
  "无法解析API响应，请稍后重试": {"zh-TW": "無法解析 API 回應，請稍後再試", "en": "Could not parse the API response. Please try again later.", "ko": "API 응답을 해석하지 못했습니다. 잠시 후 다시 시도해 주세요."},
  "读取API响应时出错，请稍后重试": {"zh-TW": "讀取 API 回應時發生錯誤，請稍後再試", "en": "Failed to read the API response. Please try again later.", "ko": "API 응답을 읽는 중 오류가 발생했습니다. 잠시 후 다시 시도해 주세요."},
  "缺少待总结的思考片段": {"zh-TW": "缺少要摘要的思考片段", "en": "Missing reasoning text to summarize", "ko": "요약할 사고 내용이 없습니다"},
  "未提供API密钥，请在设置中配置API密钥": {"zh-TW": "未提供 API 金鑰，請在設定中填入金鑰", "en": "No API key provided. Enter one in Settings.", "ko": "API 키가 없습니다. 설정에서 키를 입력해 주세요."},
  "未提供模型服务地址，请在设置中填写 API 地址": {"zh-TW": "未提供模型服務地址，請在設定中填入 API 地址", "en": "No model endpoint provided. Enter an API address in Settings.", "ko": "모델 서비스 주소가 없습니다. 설정에서 API 주소를 입력해 주세요."},
  "模型没有返回有效的思考摘要": {"zh-TW": "模型未傳回有效的思考摘要", "en": "The model did not return a valid reasoning summary", "ko": "모델이 유효한 사고 요약을 반환하지 않았습니다"},
  "模型服务地址不是有效的 URL，请检查后重试": {"zh-TW": "模型服務地址不是有效的 URL，請檢查後重試", "en": "The model endpoint is not a valid URL. Please check and try again.", "ko": "모델 서비스 주소가 유효한 URL이 아닙니다. 확인 후 다시 시도해 주세요."},
  "模型服务地址仅支持 http 或 https": {"zh-TW": "模型服務地址僅支援 http 或 https", "en": "The model endpoint only supports http or https", "ko": "모델 서비스 주소는 http 또는 https만 지원합니다"},
  "出于安全考虑，暂不支持内网或保留地址作为模型服务地址": {"zh-TW": "出於安全考量，暫不支援內網或保留地址作為模型服務地址", "en": "For security, private or reserved addresses are not supported as a model endpoint", "ko": "보안을 위해 사설 또는 예약 주소를 모델 서비스 주소로 사용할 수 없습니다"},
  "不支持的TTS提供商": {"zh-TW": "不支援的語音合成服務商", "en": "Unsupported TTS provider", "ko": "지원하지 않는 TTS 제공자입니다"},
  "不支持的声音类型，请使用 male 或 female": {"zh-TW": "不支援的聲音類型，請使用 male 或 female", "en": "Unsupported voice type. Use male or female.", "ko": "지원하지 않는 음성 유형입니다. male 또는 female을 사용해 주세요."},
  "不支持的Gemini TTS模型": {"zh-TW": "不支援的 Gemini TTS 模型", "en": "Unsupported Gemini TTS model", "ko": "지원하지 않는 Gemini TTS 모델입니다"},
  "不支持的Gemini语音类型": {"zh-TW": "不支援的 Gemini 語音類型", "en": "Unsupported Gemini voice", "ko": "지원하지 않는 Gemini 음성입니다"},
